package com.examservice.domain.model;import com.examservice.domain.exception.InvalidMatrixException;import java.time.Instant;import java.util.*;
public record ExamMatrix(UUID id,String name,String facultyId,UUID subjectId,int totalQuestions,List<ExamMatrixRule>rules,UUID createdBy,Instant createdAt,Instant updatedAt){public ExamMatrix{if(name==null||name.isBlank())throw new IllegalArgumentException("Matrix name is required");if(facultyId==null||facultyId.isBlank())throw new IllegalArgumentException("facultyId is required");if(totalQuestions<=0)throw new InvalidMatrixException("Total questions must be positive");rules=List.copyOf(rules);validate(totalQuestions,rules);}public static void validate(int total,List<ExamMatrixRule>r){if(r==null||r.isEmpty())throw new InvalidMatrixException("Matrix requires distribution rules");int sum=r.stream().mapToInt(ExamMatrixRule::questionCount).sum();if(sum!=total)throw new InvalidMatrixException("Rule total "+sum+" does not match matrix total "+total);long unique=r.stream().map(x->x.chapterId()+":"+x.topicId()+":"+x.difficulty()).distinct().count();if(unique!=r.size())throw new InvalidMatrixException("Duplicate distribution rule");}}
